<h1>Cestino — <?= e($ws['name']) ?></h1><p class="muted">Solo il proprietario del workspace può ripristinare o eliminare definitivamente. Questa azione non è annullabile.</p><h2>Documenti</h2><?php if (!$documents): ?><p>Nessun documento eliminato.</p><?php else: ?><table class="card"><tr><th>Titolo</th><th>Eliminato</th><th>Azioni</th></tr><?php foreach($documents as $d): ?><tr><td><?= e($d['title']) ?></td><td><?= e($d['deleted_at']) ?></td><td><form method="post" action="/trash/documents/<?= (int)$d['id'] ?>/restore" class="inline-form"><?= \Archium\Support\Csrf::field() ?><button class="btn-sm">Ripristina</button></form> <form method="post" action="/trash/documents/<?= (int)$d['id'] ?>/purge" class="inline-form"><?= \Archium\Support\Csrf::field() ?><button class="btn-sm danger">Elimina definitivamente</button></form></td></tr><?php endforeach; ?></table><?php endif; ?><h2>Raccolte</h2><?php if (!$collections): ?><p>Nessuna raccolta eliminata.</p><?php else: ?><table class="card"><tr><th>Raccolta</th><th>Eliminata</th><th>Azioni</th></tr><?php foreach($collections as $c): ?><tr><td><?= e($c['name']) ?></td><td><?= e($c['deleted_at']) ?></td><td><form method="post" action="/trash/collections/<?= (int)$c['id'] ?>/restore" class="inline-form"><?= \Archium\Support\Csrf::field() ?><button class="btn-sm">Ripristina</button></form> <form method="post" action="/trash/collections/<?= (int)$c['id'] ?>/purge" class="inline-form"><?= \Archium\Support\Csrf::field() ?><button class="btn-sm danger">Elimina definitivamente</button></form></td></tr><?php endforeach; ?></table><?php endif; ?>